-- ============================================================
-- ALTER: fims.budget_allocation — drop memo_ref_no
-- A memo request is identified by request_referrence_no now (RR-001, RR-002, ... generated by the database, see
-- 19 - budget_allocation_add_request_referrence_no.sql). memo_ref_no only ever held the form's generated
-- allocation number (e.g. "CBA 2026-42-86-01"), the same value for every request made from the same form, so it
-- identified nothing. BudgetAllocationService, the Memo Requests page and the form no longer read or write it.
--
-- THIS DELETES THE DATA in that column. Nothing else depends on it: its index goes with it, and no view,
-- function, trigger or constraint refers to it (if one ever does, the DROP stops with an error instead of
-- silently taking that object with it — there is deliberately no CASCADE).
-- Idempotent: safe to run any number of times (a database that never had the column is left alone).
-- ============================================================
DROP INDEX IF EXISTS fims.idx_budget_allocation_memo_ref_no;

ALTER TABLE fims.budget_allocation
    DROP COLUMN IF EXISTS memo_ref_no;
